proposition = new Map(); proposition.set('mesure', 'Planifier le déploiement de technologies de stockage d’énergie et de mécanismes nécessaires à l’équilibre d’un système énergétique 100 % renouvelable'); proposition.set('reponse', 1); programmes.push(proposition);
