proposition = new Map(); proposition.set('mesure', 'Créer un droit opposable à la protection contre les fortes chaleurs, qui oblige les bailleurs à équiper les logements présentant des risques de surchauffe pour les rendre habitables (volets, stores, brasseurs d’air, films solaires)'); proposition.set('reponse', 1); programmes.push(proposition);
