proposition = new Map(); proposition.set('mesure', 'Optimiser les usages de l’énergie dans tous les secteurs, notamment dans le tertiaire (extinction nocturne des bâtiments, équipements LED obligatoires) pour réduire la demande globale en énergie'); proposition.set('reponse', 1); programmes.push(proposition);
proposition = new Map(); proposition.set('mesure', 'Déployer l’éolien en mer, posé et flottant, pour atteindre au moins 45 gigawatts de puissance installée en 2050, ainsi que les énergies marines renouvelables (EMR), comme l’hydrolien ou l’énergie de la houle, dans le cadre du plan de bifurcation énergétique'); proposition.set('reponse', 1); programmes.push(proposition);
