proposition = new Map(); proposition.set('mesure', 'Investir plus fortement l’Organisation maritime internationale (OMI) pour soutenir l’objectif de neutralité carbone du transport maritime en 2050 et l’amélioration des conditions sociales des marins à l’échelle internationale'); proposition.set('reponse', 1); programmes.push(proposition);
