proposition = new Map(); proposition.set('mesure', 'Défendre les emplois de marins contre la concurrence déloyale, le dumping social et la Commission européenne (remorquage portuaire, construction et entretien des parcs éoliens maritimes, transports de passagers dans la Manche, la Méditerranée ou entre la Corse et le continent, etc.)'); proposition.set('reponse', 1); programmes.push(proposition);
