proposition = new Map(); proposition.set('mesure', 'Relancer les ports français et moderniser les infrastructures portuaires dans une logique multimodale mer-rail-fluvial d’électrification, de décarbonation et de soutien aux énergies renouvelables ; favoriser le débarquement des marchandises de transit européen dans les ports français de Marseille et du Havre'); proposition.set('reponse', 1); programmes.push(proposition);
proposition = new Map(); proposition.set('mesure', 'Stopper les projets industriels de production d’énergie bois et mettre en place une hiérarchisation des usages : le bois d’œuvre d’abord, l’énergie en dernier recours'); proposition.set('reponse', 1); programmes.push(proposition);
proposition = new Map(); proposition.set('mesure', 'Réviser les règles de concurrence appliquées, entre autres choses, aux services publics, et qui nous ont notamment contraint à la libéralisation de biens communs comme l’énergie, le transport et les télécoms'); proposition.set('reponse', 1); programmes.push(proposition);
