proposition = new Map(); proposition.set('mesure', 'Obliger les entreprises à adopter une comptabilité carbone pour les émissions directes et indirectes de GES certifiée par un organisme public agréé en commençant par les secteurs les plus polluants – énergie, transport, bâtiment, industrie lourde – puis selon la taille des entreprises, accompagnée d’une trajectoire de baisse de leurs émissions'); proposition.set('reponse', 1); programmes.push(proposition);
proposition = new Map(); proposition.set('mesure', 'Définir, avec la communauté internationale, une doctrine de sécurisation des sites nucléaires en zones de guerre et soutenir la protection immédiate des réacteurs en Ukraine et au Moyen-Orient, par la présence de l’ONU, avec l’appui de l’Agence internationale de l’énergie atomique (AIEA)'); proposition.set('reponse', 1); programmes.push(proposition);
